#!/usr/bin/env python3
"""Versioned sparse detector ownership union; synthetic helper contracts."""
from pathlib import Path
import os,subprocess,tempfile
ROOT=Path(__file__).resolve().parents[2]
source=Path(os.environ.get('AIDOKU_TEST_SEED_TYPE',str(ROOT/'Aidoku/Core/Translation/NativeEngine/OCR/NativeOCRDetectorSeedEvidence.swift')))
HARNESS='import Foundation\ntypealias E=NativeOCRDetectorSeedEvidence\nfunc component(_ x:Int=1,_ count:Int=2,_ runs:Int=1,_ y:Int=1)->E.Component { .init(seed:y*32768+x,pixelCount:count*runs,meanProbability:0.95,runs:(0..<runs).map{.init(y:y+$0,x:x,count:count)}) }\nfunc owner(_ id:String,_ version:Int=2,_ trusted:[E.Component]=[component()],_ ambiguous:[E.Component]=[],_ candidates:[E.Candidate]=[])->E {\n E(ownerID:id,parentBoxIndex:0,provenance:version==2 ? "db-complete-cc-candidates-v2":"db-4connected-original-cells-v1",threshold:0.9,mapOriginX:0,mapOriginY:0,mapFullWidth:32768,mapFullHeight:32768,sourceWidth:1024,sourceHeight:1024,components:trusted,ownershipVersion:version==2 ? 2:nil,completeCCScan:version==2 ? true:nil,ambiguousComponents:version==2 ? ambiguous:nil,candidateComponents:version==2 ? candidates:nil)\n}\nvar count=0\nfunc check(_ v:Bool,_ label:String){count+=1;if !v{FileHandle.standardError.write(Data(("FAIL "+label+"\\n").utf8));exit(1)}}\nlet cc=component(), a=owner("a"), b=owner("b")\nfor reversed in [false,true] {\n func union(_ x:E,_ y:E)->[E]? {E.preservingUnion(reversed ? [[y],[x]]:[[x],[y]])}\n check(union(a,b)==[a,b],"v2 identical sharedCC allowed")\n check(union(owner("a",1),owner("b",1))==nil,"v1 sharedCC rejected")\n check(union(a,owner("b",1,[component(8)]))==nil,"mixed version rejected")\n check(union(a,owner("a",2,[component(8)]))==nil,"same owner mismatch")\n check(union(a,a)==[a],"owner exact dedup")\n let amb=owner("b",2,[],[cc]);check(union(a,amb)==[a,amb],"ambiguous scope retained, no promotion")\n let candidate=owner("b",2,[],[],[.init(component:cc,competingOwnerIDs:["a"],outsideCompetingCells:[1])])\n check(union(a,candidate)==[a,candidate],"candidate scope retained, no promotion")\n check(union(a,owner("b",2,[component(1,3)]))==nil,"same seed different runs")\n var bad=a;bad.completeCCScan=false;check(union(bad,b)==nil,"incomplete false")\n bad=a;bad.completeCCScan=nil;check(union(bad,b)==nil,"incomplete missing")\n bad=a;bad.ambiguousComponents=nil;check(union(bad,b)==nil,"missing v2 list")\n bad=a;bad.ownershipVersion=3;check(union(bad,b)==nil,"future version")\n check(E.preservingUnion([[a],nil])==nil,"missing evidence")\n let invalid=owner("a",2,[],[],[.init(component:cc,competingOwnerIDs:["a"],outsideCompetingCells:[1])]);check(!invalid.isValid,"self competitor")\n let nooutside=owner("a",2,[],[],[.init(component:cc,competingOwnerIDs:["b"],outsideCompetingCells:[2])]);check(!nooutside.isValid,"outside count equal all pixels")\n let duplicateScope=owner("a",2,[cc],[cc]);check(!duplicateScope.isValid,"duplicate seed within scopes")\n let large=component(0,32768,8)\n let huge=owner("large",2,[],[large]);check(huge.isValid,"ambiguous cap boundary")\n check(union(huge,owner("other",2,[component(3,1,1,30)]))==nil,"ambiguous included total pixel cap")\n let largeCandidate=owner("large",2,[],[],[.init(component:large,competingOwnerIDs:["other"],outsideCompetingCells:[1])]);check(largeCandidate.isValid,"candidate cap boundary")\n check(union(largeCandidate,owner("other",2,[component(3,1,1,30)]))==nil,"candidate included total pixel cap")\n let many=owner("many",2,[],[component(1,1,4096)]);check(many.isValid,"run boundary")\n check(union(many,owner("other",2,[component(3,1,1,5000)]))==nil,"ambiguous run total cap")\n check(union(huge,owner("sameCC",2,[],[large]))==nil,"sharedCC serialized totals counted")\n let owners=(0..<64).map{owner(String($0),2,[component($0+1)])}\n check(E.preservingUnion([owners])?.count==64,"64 owner boundary")\n check(E.preservingUnion([owners+[owner("extra",2,[component(100)])]])==nil,"65 owner rejection")\n}\nprint("SEED_V2_INDEPENDENT \\(count) PASS")\n'
with tempfile.TemporaryDirectory(prefix='aidoku-seed-v2-independent-') as temporary:
    p=Path(temporary);(p/'main.swift').write_text(HARNESS)
    roi_source = ROOT / 'Aidoku/Core/Translation/NativeEngine/OCR/NativeOCRSourceROIProbabilityEvidence.swift'
    subprocess.run(['swiftc','-O',str(roi_source),str(source),str(p/'main.swift'),'-o',str(p/'test')],check=True)
    subprocess.run([str(p/'test')],check=True)
